/* DEV32: softer everyday clothing colours and individually coloured new students.
 *
 * Muted32  - realistic, low-saturation palettes (neutrals, denim, earth tones and a
 *            few muted colours) used for every attendee, booth representative and the
 *            pants/shoes of helpers. Volunteer purple (#7038aa) is untouched.
 * StudentLooks32 - the seven scanned students (students17/*.glb) each have ONE photo
 *            texture for skin, clothes and hair. The role maps below say, for every
 *            texel of that texture, whether it is the top/coat (1), pants (2), shoes (3),
 *            hair (7) or left as photographed (0: skin, face, inner layers, backpack).
 *            At load time the clothing and hair texels are turned into a neutral fabric
 *            shade (folds and weave kept), then every duplicate is tinted with its own
 *            top, pants, shoes and hair colour in the existing crowd shader.
 * The .glb files in students17 are not modified.
 * Role maps: 1024 x 1024 bytes, gzip + base64 (value | 128 = UV gutter texel).
 */

const Muted32 = (() => {
  'use strict';
  // [sRGB, weight]. Tops = shirts, hoodies, sweaters, jackets and coats.
  const P = {
    top: [['#1f1f22',10],['#3a3c40',8],['#5d6166',5],['#8b8e92',8],['#b7b9bb',4],['#e4e1da',6],['#d8cdb8',4],['#b9a88c',4],['#8c7a64',3],
      ['#1f2a44',8],['#34466a',4],['#4f6a8c',5],['#7d93ab',3],['#2f4a3a',4],['#555c3a',4],['#86927a',3],['#5e2b33',4],['#7c3a33',3],
      ['#9a5b3f',2],['#b48683',3],['#a88f4d',2],['#a07a52',3],['#5a4334',4],['#3f6b6b',2]],
    bottom: [['#27344f',10],['#3d5475',8],['#6d86a6',5],['#2a2c30',8],['#1c1c1e',7],['#4b4e54',5],['#6b6e73',4],['#a8977a',5],['#8a7658',3],
      ['#5a5c40',3],['#26304a',4],['#4d3b2e',3],['#9fa2a6',2],['#d8d2c4',1]],
    shoes: [['#e0e0dc',10],['#cfc8b8',4],['#1e1e1f',9],['#3b3d41',4],['#7a7d82',4],['#5a412f',4],['#8d6c48',3],['#2c3550',3],['#3c4a3c',1],['#6a2e31',1]],
    hair: [['#171312',8],['#2a1e17',10],['#43301f',9],['#634630',7],['#826044',5],['#9e7f55',5],['#c2a36c',4],['#6b3520',3],['#8e4a2a',1]],
    hairDark: [['#120f0e',12],['#1d1612',12],['#2a1e17',9],['#43301f',5],['#634630',2],['#6b3520',1]],
    // Backpacks, caps and small trims on the original characters.
    accent: [['#1f1f22',8],['#3a3c40',6],['#1f2a44',6],['#555c3a',4],['#8b8e92',4],['#a8977a',4],['#5e2b33',3],['#2f4a3a',3],['#4f6a8c',3],['#a07a52',3],['#e4e1da',2]]
  };
  const hexToRgb = h => [1, 3, 5].map(k => parseInt(h.slice(k, k + 2), 16) / 255);
  function rgbToHsl([r, g, b]) {
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b), l = (mx + mn) / 2; let h = 0, s = 0;
    if (mx !== mn) {const d = mx - mn; s = l > .5 ? d / (2 - mx - mn) : d / (mx + mn);
      h = mx === r ? (g - b) / d + (g < b ? 6 : 0) : mx === g ? (b - r) / d + 2 : (r - g) / d + 4; h *= 60;}
    return [h, s, l];
  }
  function hslToHex(h, s, l) {
    h = ((h % 360) + 360) % 360 / 360;
    const f = n => {const k = (n + h * 12) % 12; return l - s * Math.min(l, 1 - l) * Math.max(-1, Math.min(k - 3, 9 - k, 1));};
    return '#' + [f(0), f(8), f(4)].map(v => Math.round(Math.max(0, Math.min(1, v)) * 255).toString(16).padStart(2, '0')).join('');
  }
  function color(r, kind) {
    const list = P[kind] || P.top; let total = 0; for (const e of list) total += e[1];
    let t = r() * total, base = list[0][0];
    for (const [hex, w] of list) {if ((t -= w) <= 0) {base = hex; break;}}
    let [h, s, l] = rgbToHsl(hexToRgb(base));
    h += (r() - .5) * 12; s = Math.min(kind.startsWith('hair') ? .55 : .5, s * (.85 + r() * .3)); l = Math.max(.05, Math.min(.92, l + (r() - .5) * .08));
    if (!kind.startsWith('hair') && s > .12 && h > 250 && h < 322) h = h < 286 ? 246 : 326;   // purple stays reserved for volunteers
    return hslToHex(h, s, l);
  }
  function unique(r, set, kind) {let s, n = 0; do {s = color(r, kind);} while (set.has(s) && ++n < 60); set.add(s); return s;}
  return {color, unique, palettes: P};
})();
window.Muted32 = Muted32;

const StudentLooks32 = (() => {
  'use strict';
  const SIZE = 1024;
  const MAPS = {"fig0027": "","fig0098": "","fig0143": "","fig0147": "","fig0151": "","fig0160": "","fig0165": ""};
  const HAIR_SET = {fig0098: 'hairDark'};
  // Relative fabric contrast kept per role (folds, knit, denim weave, hair strands).
  const CONTRAST = {1: .30, 2: .26, 3: .30, 7: .42}, MEAN = .66;
  const decoded = new Map(), report = {};
  const LUT = new Float32Array(256);
  for (let i = 0; i < 256; i++) {const v = i / 255; LUT[i] = v <= .04045 ? v / 12.92 : ((v + .055) / 1.055) ** 2.4;}
  const toSRGB8 = v => {const s = v <= .0031308 ? 12.92 * v : 1.055 * Math.pow(v, 1 / 2.4) - .055; return Math.max(0, Math.min(255, Math.round(s * 255)));};
  async function roles(id) {
    if (decoded.has(id)) return decoded.get(id);
    const src = MAPS[id]; if (!src) return null;
    const p = (async () => {
      const gz = Uint8Array.from(atob(src), c => c.charCodeAt(0));
      const out = new Uint8Array(await new Response(new Blob([gz]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());
      if (out.length !== SIZE * SIZE) throw Error('role map size ' + out.length);
      return out;
    })();
    decoded.set(id, p); return p;
  }
  function median(values) {const a = Float32Array.from(values).sort(); return a.length ? a[a.length >> 1] : 0;}
  // Clothing and hair texels become a neutral fabric shade; skin, face and kept layers stay as photographed.
  function neutralize(d, map) {
    const n = SIZE * SIZE, L = new Float32Array(n), B = new Float32Array(n);
    for (let i = 0, k = 0; i < n; i++, k += 4) L[i] = LUT[d[k]] * .2126 + LUT[d[k + 1]] * .7152 + LUT[d[k + 2]] * .0722;
    for (let y = 0; y < SIZE; y++) for (let x = 0; x < SIZE; x++) {   // 3x3 average: calmer dark fabrics
      let s = 0, c = 0;
      for (let dy = -1; dy <= 1; dy++) {const yy = y + dy; if (yy < 0 || yy >= SIZE) continue;
        for (let dx = -1; dx <= 1; dx++) {const xx = x + dx; if (xx < 0 || xx >= SIZE) continue; s += L[yy * SIZE + xx]; c++;}}
      B[y * SIZE + x] = s / c;
    }
    const stats = {};
    for (const r of [1, 2, 3, 7]) {
      const vals = [];
      for (let i = 0; i < n; i += 3) if (map[i] === r) vals.push(L[i]);
      if (vals.length < 50) continue;
      const med = Math.max(1e-4, median(vals)), dark = med < .06, src = dark ? B : L, dev = [];
      for (let i = 0; i < n; i += 3) if (map[i] === r) dev.push(Math.abs(src[i] / med - 1));
      const mad = Math.max(1e-4, median(dev) * 1.4826), k = Math.min(1, CONTRAST[r] / mad);
      stats[r] = {med: +med.toFixed(4), contrast: +k.toFixed(3)};
      for (let i = 0, j = 0; i < n; i++, j += 4) {
        const m = map[i]; if ((m & 127) !== r) continue;
        const v = m & 128 ? MEAN : Math.max(.02, Math.min(1, MEAN * (1 + k * (src[i] / med - 1)))), s = toSRGB8(v);
        d[j] = d[j + 1] = d[j + 2] = s;
      }
    }
    return stats;
  }
  async function prepare(model, bin, maps, parts) {
    const id = model.id;
    if (!MAPS[id]) return false;
    try {
      const map = await roles(id);
      const mi = parts?.[0]?.materialIndex ?? 0, mat = model.j.materials[mi];
      const ti = mat?.pbrMetallicRoughness?.baseColorTexture?.index;
      const im = await CharacterFitting.imageFromTexture(model.j, bin, ti);
      const c = document.createElement('canvas'); c.width = c.height = SIZE;
      const ctx = c.getContext('2d', {willReadFrequently: true}); ctx.drawImage(im, 0, 0, SIZE, SIZE); im.close?.();
      const img = ctx.getImageData(0, 0, SIZE, SIZE), stats = neutralize(img.data, map); ctx.putImageData(img, 0, 0);
      if (gl.isContextLost()) throw Error('graphics context lost');
      const tex = CharacterFitting.canvasTexture(c);
      const roleTex = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, roleTex);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false); gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.R8, SIZE, SIZE, 0, gl.RED, gl.UNSIGNED_BYTE, map);
      gl.pixelStorei(gl.UNPACK_ALIGNMENT, 4);
      for (const [p, v] of [[gl.TEXTURE_MIN_FILTER, gl.NEAREST], [gl.TEXTURE_MAG_FILTER, gl.NEAREST], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, p, v);
      gl.bindTexture(gl.TEXTURE_2D, null);
      const old = maps.get(mi);
      if (old) {releaseEmbeddedTexture(old); const at = model.textureRefs18?.indexOf(old); if (at >= 0) model.textureRefs18.splice(at, 1);}
      maps.set(mi, tex);
      (model.textureRefs18 ||= []).push(tex, roleTex);
      model.roleMap32 = roleTex; model.looks32 = true;
      report[id] = {ready: true, stats};
      return true;
    } catch (e) {
      report[id] = {ready: false, error: e.message || String(e)};
      console.warn('Student outfit colours unavailable for ' + id + ':', e);
      return false;
    }
  }
  // Called by the crowd renderer and by single-character drawing, per mesh part.
  function bind(b) {
    const m = b && b.roleMap;
    gl.uniform1i(uniforms.uRoleMapped, m ? 1 : 0);
    gl.activeTexture(gl.TEXTURE5); gl.bindTexture(gl.TEXTURE_2D, m || whiteBaseMap); gl.uniform1i(uniforms.uRoleMap, 5); gl.activeTexture(gl.TEXTURE0);
  }
  // One stable outfit per person: top/coat, pants, shoes and hair colours (hair uses the accent slot).
  function outfit(index, seed, model) {
    const r = CrowdWardrobe.rng((seed ^ CrowdWardrobe.hash('student32:' + index)) >>> 0), lin = CrowdWardrobe.linear;
    const top = Muted32.color(r, 'top'), pants = Muted32.color(r, 'bottom'), shoes = Muted32.color(r, 'shoes'), hair = Muted32.color(r, HAIR_SET[model?.id] || 'hair');
    return {id: index, shirt: top, pants, shoes, accent: hair, hair, colors: [...lin(top), ...lin(pants), ...lin(shoes), ...lin(hair)],
      backpack: false, hat: false, volunteer: false, flags: [0, 0, 0, 1], studentLooks32: true};
  }
  return {prepare, bind, outfit, roles, report, get models() {return Object.keys(MAPS);}};
})();
window.StudentLooks32 = StudentLooks32;
